type ModelRow<D extends ContractMap, N extends keyof D> = {
    readonly [F in keyof D[N]['columns']]: FieldValue<D, N, F>;
};

type MutationForm<Values extends object, Result> = Omit<
    FormDescriptor<Values, Readonly<Record<string, FieldDefinition>>, Record<string, never>>,
    'submission'
> & {
    readonly submission: {
        submit(
            this: void,
            values: Values,
            context: { readonly signal: AbortSignal },
        ): Promise<MutationSubmissionResult<Result>>;
    };
};

type MutationSubmissionResult<Result> = | Exclude<SubmissionResult, { status: 'success' }>
    | {
          readonly status: 'success';
          readonly value:
              | { readonly resolved: true; readonly data: Result }
              | { readonly resolved: false; readonly error: MutationResultError };
      };

type QueryArgs = {
    id?: string | number;
    filters?: { [key: string]: ReadonlyJSONValue };
    include?: { [key: string]: IncludeArgs };
    order?: [string, 'asc' | 'desc'][];
    limit?: number;
};

type UpdateInput<D extends ContractMap, N extends keyof D> = {
    id: RecordId<D, N>;
} & {
    [F in RequiredFields<D, N, 'update'>]: FieldValue<D, N, F>;
} & {
    [F in Exclude<Writable<D, N>, RequiredFields<D, N, 'update'>>]?: FieldValue<D, N, F>;
};

